function safe(d,m){return d<=1.5&&m<=30;}
const tests=[[1,30],[1.5,30],[2,10],[0.5,60]];
console.log(JSON.stringify({feature:'IP68 rating check',tests:tests.map(t=>({depth_m:t[0],min:t[1],within_rating:safe(t[0],t[1])}))}));

const angles=[0,45,90,135,180];
const state=angles.map(a=>({angle:a,mode:a<30?'closed':a<150?'flex':'flat'}));
console.log(JSON.stringify({feature:'Foldable display hinge states',states:state,glass:'ultra-thin glass'}));

const themes={light:{bg:'#fff',fg:'#111'},dark:{bg:'#0b0e14',fg:'#e8f1ff'}};
let cur='light';
function toggle(){cur=cur==='light'?'dark':'light';return themes[cur];}
console.log(JSON.stringify({feature:'Dark mode toggle',after_one:toggle(),after_two:toggle(),oled_note:'true black saves OLED power'}));

const desks={1:[],2:[],3:[]};
function move(app,d){Object.keys(desks).forEach(k=>{desks[k]=desks[k].filter(a=>a!==app);});desks[d].push(app);return desks;}
move('browser',1);move('editor',2);move('music',3);move('editor',1);
console.log(JSON.stringify({feature:'Virtual desktops',desks:desks}));

const words='live captions turn speech into text on the device itself'.split(' ');
let t=0;const lines=[];
words.forEach((w,i)=>{if(i%4===0){t+=2;lines.push({at_s:t,text:''});}lines[lines.length-1].text+=' '+w;});
console.log(JSON.stringify({feature:'Live captions',caption_lines:lines.map(l=>({at_s:l.at_s,text:l.text.trim()}))}));

const cap=4000,drain={normal:320,saver:150};
const hrs={};Object.keys(drain).forEach(k=>{hrs[k]=+(cap/drain[k]).toFixed(1);});
console.log(JSON.stringify({feature:'Battery saver mode',hours:hrs,extension_pct:Math.round((hrs.saver/hrs.normal-1)*100)}));

const bitrate=12,res='1080p';
const mbPerMin=bitrate*60/8;
console.log(JSON.stringify({feature:'Built-in screen recording',resolution:res,bitrate_mbps:bitrate,mb_per_min:+mbPerMin.toFixed(1),ten_min_mb:+mbPerMin.toFixed(1)*10}));

function xor(s,k){return s.split('').map((c,i)=>String.fromCharCode(c.charCodeAt(0)^k.charCodeAt(i%k.length))).join('');}
const msg='secret plans',key='k3y';
const enc=xor(msg,key);
console.log(JSON.stringify({feature:'End-to-end encryption (teaching cipher)',roundtrip_ok:xor(enc,key)===msg,note:'real E2EE uses audited protocols like Signal'}));

let cloud={v:3,doc:'hello'},local={v:3,doc:'hello'};
local.doc='hello world';local.v=4;
function push(){if(local.v>cloud.v){cloud={...local};}return cloud;}
console.log(JSON.stringify({feature:'Cloud sync delta push',after_push:push(),conflict_rule:'higher version wins, loser kept in history'}));

const queue=[];
function edit(op){queue.push(op);return 'queued offline: '+op;}
function reconnect(){const n=queue.length;queue.length=0;return 'synced '+n+' ops';}
edit('add note');edit('rename file');
console.log(JSON.stringify({feature:'Offline mode queue',step1:'2 edits queued',step2:reconnect()}));

const ops=[{u:'a',ins:'Hello',at:0},{u:'b',ins:' world',at:5}];
let doc='';
ops.sort((x,y)=>x.at-y.at).forEach(o=>{doc=doc.slice(0,o.at)+o.ins+doc.slice(o.at);});
console.log(JSON.stringify({feature:'Real-time collaboration merge',ops:ops.map(o=>o.u+':insert@'+o.at),merged_doc:doc,algorithm:'operational transform orders inserts'}));

const hist=[{v:1,t:'draft'},{v:2,t:'draft + intro'},{v:3,t:'draft + intro + data'}];
function restore(v){return hist.find(h=>h.v===v);}
console.log(JSON.stringify({feature:'Version history autosave',versions:hist.length,restore_v2:restore(2)}));

const crypto=require('crypto');
function code(secret,counter){const h=crypto.createHmac('sha1',secret).update(Buffer.from(String(counter))).digest('hex');
const off=parseInt(h.slice(-1),16);const n=(parseInt(h.substr(off*2,8),16)&0x7fffffff)%1000000;return String(n).padStart(6,'0');}
console.log(JSON.stringify({feature:'Two-factor TOTP',counter:123456,code:code('demo-secret',123456),window_s:30}));

const subs=[{u:'a',topics:['news']},{u:'b',topics:['news','deals']}];
function send(topic,msg){return subs.filter(s=>s.topics.includes(topic)).map(s=>({to:s.u,msg}));}
console.log(JSON.stringify({feature:'Push notifications',delivered:send('news','breaking: ...'),via:'APNs/FCM, opt-in only'}));

const enrolled={fp:'tmpl_9f2',face:'tmpl_44a'};
function auth(kind,sample){return enrolled[kind]===sample;}
console.log(JSON.stringify({feature:'Biometric login',fingerprint_match:auth('fp','tmpl_9f2'),face_mismatch:auth('face','tmpl_xx'),note:'templates never leave the device'}));

const patterns={tap:[0,30],double:[0,30,60,30],alert:[0,80,40,80,40,120]};
function play(p){return patterns[p].reduce((a,b)=>a+b,0);}
console.log(JSON.stringify({feature:'Haptic feedback',patterns:Object.keys(patterns),total_ms:{tap:play('tap'),alert:play('alert')},actuator:'linear resonant actuator'}));

const crypto=require('crypto');
function token(pan){return crypto.createHash('sha256').update(pan).digest('hex').slice(0,16);}
console.log(JSON.stringify({feature:'NFC contactless payments',token:token('4111111111111111'),mhz:13.56,note:'real card number never transmitted'}));

const els=[{t:'button',label:'Buy now'},{t:'img',label:''},{t:'input',label:'Email'}];
const audit=els.map(e=>({type:e.t,ok:!!e.label,label:e.label||'(missing - flagged)'}));
console.log(JSON.stringify({feature:'Screen reader label audit',elements:audit,pass_rate:'2/3'}));

function lum(h){const c=[1,3,5].map(i=>{let v=parseInt(h.substr(i,2),16)/255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4);});return 0.2126*c[0]+0.7152*c[1]+0.0722*c[2];}
function ratio(a,b){const x=lum(a),y=lum(b);return +((Math.max(x,y)+0.05)/(Math.min(x,y)+0.05)).toFixed(2);}
console.log(JSON.stringify({feature:'Text contrast (WCAG)',pairs:[{fg:'#000000',bg:'#ffffff',ratio:ratio('000000','ffffff')},{fg:'#777777',bg:'#ffffff',ratio:ratio('777777','ffffff')}],aa_min:4.5}));
